struct Cart  { int qty; int unit_cents; bool promo; };
struct Quote { int total; int tax; };
[[nodiscard]] Quote price(const Cart& c) {          // pure core
    int total = c.qty * c.unit_cents;
    if (c.promo) total -= total / 10;
    return {total, total / 10};
}
int main() {                       // shell: read, decide, print
    const Cart c = read_cart(std::cin);
    const Quote q = price(c);
    std::cout << q.total + q.tax << '\n';
}

