enum class Tier { basic, pro, team };
consteval int monthly_cents(Tier t) {          // pure by construction
    switch (t) {
        case Tier::basic: return 0;
        case Tier::pro:   return 2900;
        case Tier::team:  return 9900;
    }
    return 0;
}
